  "radio": {
    dir: "radio",
    category: "atoms",
    examples: [
      { label: "Default", code: "<RadioGroup defaultValue=\"pro\">\n  <Column snug>\n    <Row snug alignStart>\n      <Radio value=\"hobby\" />\n      <Column>\n        <Typography small medium>Hobby</Typography>\n        <Typography tiny muted>For personal projects and experiments.</Typography>\n      </Column>\n    </Row>\n    <Row snug alignStart>\n      <Radio value=\"pro\" />\n      <Column>\n        <Typography small medium>Pro</Typography>\n        <Typography tiny muted>For growing teams that need more control.</Typography>\n      </Column>\n    </Row>\n    <Row snug alignStart>\n      <Radio value=\"enterprise\" />\n      <Column>\n        <Typography small medium>Enterprise</Typography>\n        <Typography tiny muted>Advanced security, compliance, and support.</Typography>\n      </Column>\n    </Row>\n  </Column>\n</RadioGroup>", render: e_atoms_radio_example_0 },
      { label: "Variant - inline", code: "<Radio checked small>Pro, for growing teams that need more control.</Radio>", render: e_atoms_radio_example_1 },
      { label: "Variant - card", code: "<Row snug>\n  <Column fill>\n    <Card padded>\n      <Column snug>\n        <Radio />\n        <Typography small semibold>Hobby</Typography>\n        <Typography tiny muted>For personal projects and experiments.</Typography>\n      </Column>\n    </Card>\n  </Column>\n  <Column fill>\n    <Card padded selected>\n      <Column snug>\n        <Radio checked />\n        <Typography small semibold>Pro</Typography>\n        <Typography tiny muted>For growing teams that need more control.</Typography>\n      </Column>\n    </Card>\n  </Column>\n  <Column fill>\n    <Card padded>\n      <Column snug>\n        <Radio />\n        <Typography small semibold>Enterprise</Typography>\n        <Typography tiny muted>Advanced security, compliance, and support.</Typography>\n      </Column>\n    </Card>\n  </Column>\n</Row>", render: e_atoms_radio_example_2 },
    ],
    donts: [
      { do: { caption: "Pre-select a sensible default so the common path needs no clicks.", code: "<Column snug>\n  <Typography small semibold>Plan</Typography>\n  <RadioGroup defaultValue=\"pro\">\n    <Radio value=\"hobby\">Hobby</Radio>\n    <Radio value=\"pro\">Pro</Radio>\n    <Radio value=\"enterprise\">Enterprise</Radio>\n  </RadioGroup>\n</Column>", render: e_atoms_radio_dont_0_do }, dont: { caption: "Leaving a radio group with nothing selected forces an extra decision and can submit empty.", code: "<View style={{ flexDirection: \"column\", gap: 8 }}>\n  <Text style={{ marginBottom: 4, fontSize: 14, lineHeight: 20, fontWeight: \"600\", color: tokens.foreground }}>Plan</Text>\n  <Radio>Hobby</Radio>\n  <Radio>Pro</Radio>\n  <Radio>Enterprise</Radio>\n</View>", render: e_atoms_radio_dont_0_dont } },
      { title: "Stacked", do: { caption: "Align the control to the first text line (mt-[3px]) so it sits beside the title, with the description flowing below.", code: "<Column snug>\n  <Row snug alignStart>\n    <Radio checked />\n    <Column>\n      <Typography small medium>Pro</Typography>\n      <Typography tiny muted>For growing teams that need more control.</Typography>\n    </Column>\n  </Row>\n</Column>", render: e_atoms_radio_dont_1_do }, dont: { caption: "With items-center the input floats to the vertical middle of a two-line label, leaving it visually unattached to the title it controls.", code: "<View style={{ flexDirection: \"column\", gap: 10 }}>\n  <View style={{ flexDirection: \"row\", alignItems: \"center\", gap: 8 }}>\n    <Radio checked />\n    <View>\n      <Text style={{ fontSize: 13, fontWeight: \"500\", color: tokens.foreground }}>Pro</Text>\n      <Text style={{ fontSize: 12, lineHeight: 16, color: tokens[\"muted-foreground\"] }}>For growing teams that need more control.</Text>\n    </View>\n  </View>\n</View>", render: e_atoms_radio_dont_1_dont } },
      { title: "Inline", do: { caption: "Use gap-6 between options (gap-2 inside each) so every label clearly pairs with its own control.", code: "<RadioGroup row defaultValue=\"hobby\">\n  <Radio value=\"hobby\" small>Hobby</Radio>\n  <Radio value=\"pro\" small>Pro</Radio>\n  <Radio value=\"enterprise\" small>Enterprise</Radio>\n</RadioGroup>", render: e_atoms_radio_dont_2_do }, dont: { caption: "Cramped gap-1 between options makes each label blur into the next radio, so it is hard to tell which dot belongs to which choice.", code: "<View style={{ flexDirection: \"row\", flexWrap: \"wrap\", gap: 6 }}>\n  <Radio checked small>Hobby</Radio>\n  <Radio small>Pro</Radio>\n  <Radio small>Enterprise</Radio>\n</View>", render: e_atoms_radio_dont_2_dont } },
      { title: "Card", do: { caption: "Give the selected card a primary border and tinted fill so the whole tile reads as chosen, not just the dot.", code: "<Row snug>\n  <Column fill>\n    <Card padded selected>\n      <Column snug>\n        <Radio checked />\n        <Typography small semibold>Pro</Typography>\n        <Typography tiny muted>For growing teams.</Typography>\n      </Column>\n    </Card>\n  </Column>\n  <Column fill>\n    <Card padded>\n      <Column snug>\n        <Radio />\n        <Typography small semibold>Enterprise</Typography>\n        <Typography tiny muted>Advanced security.</Typography>\n      </Column>\n    </Card>\n  </Column>\n</Row>", render: e_atoms_radio_dont_3_do }, dont: { caption: "When the selected card keeps the same plain border, only the tiny native dot signals the choice and the active card is easy to miss.", code: "<View style={{ flexDirection: \"row\", gap: 8 }}>\n  <View style={{ flexGrow: 1, flexShrink: 1, flexBasis: \"0%\", flexDirection: \"column\", borderRadius: 6, borderWidth: 1, borderColor: tokens.border, padding: 14 }}>\n    <Radio checked style={{ marginBottom: 8 }} />\n    <Text style={{ fontSize: 13, fontWeight: \"600\", color: tokens.foreground }}>Pro</Text>\n    <Text style={{ fontSize: 12, lineHeight: 16, color: tokens[\"muted-foreground\"] }}>For growing teams.</Text>\n  </View>\n  <View style={{ flexGrow: 1, flexShrink: 1, flexBasis: \"0%\", flexDirection: \"column\", borderRadius: 6, borderWidth: 1, borderColor: tokens.border, padding: 14 }}>\n    <Radio style={{ marginBottom: 8 }} />\n    <Text style={{ fontSize: 13, fontWeight: \"600\", color: tokens.foreground }}>Enterprise</Text>\n    <Text style={{ fontSize: 12, lineHeight: 16, color: tokens[\"muted-foreground\"] }}>Advanced security.</Text>\n  </View>\n</View>", render: e_atoms_radio_dont_3_dont } },
    ],
  },
